(4872512, 706370, 57936, '<td valign="top">Nice colors! Looks like a bit of sensor dust (or some small flying thing...) between the trees near the top. Nice framing, too.</td>', 'Nice colors! Looks like a bit of sensor dust (or some small flying thing...) between the trees near the top. Nice framing, too.', '2008-08-07 12:05:04.000000', NULL, 1),
(4872515, 706351, 57936, '<td valign="top">A fallen Monarch! That''s rich... (The king is dead... Long live the king!)</td>', 'A fallen Monarch! That''s rich... (The king is dead... Long live the king!)', '2008-08-07 12:05:44.000000', NULL, 1),
(4872523, 705926, 57936, '<td valign="top">The exposure is a bit dark overall. Some levels/curves work could make this pop.</td>', 'The exposure is a bit dark overall. Some levels/curves work could make this pop.', '2008-08-07 12:08:34.000000', NULL, 1),
(4872532, 706427, 57936, '<td valign="top">This is a bit OOF and the bird is massively underexposed. Plus the patterns in the watter are also blurred, suggesting that there is some camera shake going on. I realize that it is a tough shooting environment, but a tripod would have helped a lot.</td>', 'This is a bit OOF and the bird is massively underexposed. Plus the patterns in the watter are also blurred, suggesting that there is some camera shake going on. I realize that it is a tough shooting environment, but a tripod would have helped a lot.', '2008-08-07 12:12:20.000000', NULL, 1),
(4872536, 705794, 57936, '<td valign="top">This is pretty cool looking, but a bit too much like animation for my tastes.</td>', 'This is pretty cool looking, but a bit too much like animation for my tastes.', '2008-08-07 12:13:02.000000', NULL, 1),
(4872545, 706307, 57936, '<td valign="top">You can barely see "her" in this shot. The angle doesn''t do anything for the image imo.</td>', 'You can barely see "her" in this shot. The angle doesn''t do anything for the image imo.', '2008-08-07 12:16:08.000000', NULL, 1),
(4872553, 706434, 57936, '<td valign="top">With the long DOF it would have been better to have the first one in focus as well...</td>', 'With the long DOF it would have been better to have the first one in focus as well...', '2008-08-07 12:19:25.000000', NULL, 1),
(4872588, 706468, 57936, '<td valign="top">OOF, crooked, the whites are blown out, the dark colors have too little detail.</td>', 'OOF, crooked, the whites are blown out, the dark colors have too little detail.', '2008-08-07 12:32:26.000000', NULL, 1),
(4872592, 705777, 57936, '<td valign="top">The focus is a bit off and the dead animal is barely in the frame.</td>', 'The focus is a bit off and the dead animal is barely in the frame.', '2008-08-07 12:34:35.000000', NULL, 1),
(4872596, 706454, 57936, '<td valign="top">A bit too much cloning of the pole, the bottom foot is mostly gone.</td>', 'A bit too much cloning of the pole, the bottom foot is mostly gone.', '2008-08-07 12:35:14.000000', NULL, 1),
(4872598, 706316, 57936, '<td valign="top">If just the horse and rider had blur it would be ok, but the entire background is blurry too...</td>', 'If just the horse and rider had blur it would be ok, but the entire background is blurry too...', '2008-08-07 12:36:30.000000', NULL, 1),
(4872600, 705684, 57936, '<td valign="top">Especially in this bright lighting, you should have enough shutter speed to stop the action. It would also be better with the ball in the picture.</td>', 'Especially in this bright lighting, you should have enough shutter speed to stop the action. It would also be better with the ball in the picture.', '2008-08-07 12:37:31.000000', NULL, 1),
(4872605, 706043, 57936, '<td valign="top">Interesting concept. I am not a fan of the border, though, and the bright patch at the neck is very distracting.</td>', 'Interesting concept. I am not a fan of the border, though, and the bright patch at the neck is very distracting.', '2008-08-07 12:39:38.000000', NULL, 1),
(4872608, 706313, 57936, '<td valign="top">This would be better if the falling goose was in focus and entirely in the frame.</td>', 'This would be better if the falling goose was in focus and entirely in the frame.', '2008-08-07 12:40:42.000000', NULL, 1),
(4872621, 704780, 72579, '<td valign="top">very nice. I like his expression.</td>', 'very nice. I like his expression.', '2008-08-07 12:45:34.000000', NULL, 1),
(4872731, 706313, 90658, '<td valign="top">That first step''s a whoopsie-daisy!  This is really funny.  How long did you have to wait for this to happen?</td>', 'That first step''s a whoopsie-daisy!  This is really funny.  How long did you have to wait for this to happen?', '2008-08-07 13:56:04.000000', NULL, 1),
(4872733, 705991, 90658, '<td valign="top">Interesting twist on reality, presenting this upside down.</td>', 'Interesting twist on reality, presenting this upside down.', '2008-08-07 13:57:37.000000', NULL, 1),
(4872734, 706366, 90658, '<td valign="top">I really like the simplicity of this.  The condensation on the bottle is wonderful, it gives the entire shot a sense of time passing.</td>', 'I really like the simplicity of this.  The condensation on the bottle is wonderful, it gives the entire shot a sense of time passing.', '2008-08-07 13:59:12.000000', NULL, 1),
(4872738, 706460, 90658, '<td valign="top">Hilarious!!!</td>', 'Hilarious!!!', '2008-08-07 14:00:12.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4872742, 706339, 90658, '<td valign="top">Nice job!  I was sort of hoping to see something like this.  The timing on this is perfect.</td>', 'Nice job!  I was sort of hoping to see something like this.  The timing on this is perfect.', '2008-08-07 14:02:48.000000', NULL, 1),
(4872748, 705847, 90658, '<td valign="top">Nice timing.  You captured that precious moment of maximum emotion.  You can see the laughter and feel the the impending pain of bruises and embarassment.</td>', 'Nice timing.  You captured that precious moment of maximum emotion.  You can see the laughter and feel the the impending pain of bruises and embarassment.', '2008-08-07 14:07:13.000000', NULL, 1),
(4872882, 706074, 16834, '<td valign="top">A bit extreme to knock it over just for this challenge?<br/>I like the framing and duotone look.</td>', 'A bit extreme to knock it over just for this challenge?I like the framing and duotone look.', '2008-08-07 15:20:28.000000', NULL, 1),
(4873245, 705991, 88822, '<td valign="top">Nice shot, and a round 8 for creativity.</td>', 'Nice shot, and a round 8 for creativity.', '2008-08-07 18:10:11.000000', NULL, 1),
(4873259, 706456, 88822, '<td valign="top">Great faces. well composed shot.</td>', 'Great faces. well composed shot.', '2008-08-07 18:13:47.000000', NULL, 1),
(4873397, 706453, 63812, '<td valign="top">excellent capture! Love his expression, and sharpness and colour of this photo.  Sure i will see this in front page.</td>', 'excellent capture! Love his expression, and sharpness and colour of this photo.  Sure i will see this in front page.', '2008-08-07 19:41:42.000000', NULL, 1),
(4873993, 706143, 87620, '<td valign="top">g</td>', 'g', '2008-08-08 00:18:59.000000', NULL, 1),
(4874732, 706426, 96574, '<td valign="top">beautiful shot. not sure if it fit the theme for me tho</td>', 'beautiful shot. not sure if it fit the theme for me tho', '2008-08-08 07:53:08.000000', NULL, 1),
(4874758, 706434, 96574, '<td valign="top">i think i wouldve liked this better if the horizon line was level</td>', 'i think i wouldve liked this better if the horizon line was level', '2008-08-08 08:23:29.000000', NULL, 1),
(4874773, 706354, 96574, '<td valign="top">interesting how the perspective makes the apple look mutantly large</td>', 'interesting how the perspective makes the apple look mutantly large', '2008-08-08 08:35:07.000000', NULL, 1),
(4874793, 706456, 67258, '<td valign="top">Probably my favourite of the challenge - those expressions are priceless, and the camera control and quick reactions needed to get a composition with technicals as good as this with such a fast moving subject shouldn''t be under-estimated.</td>', 'Probably my favourite of the challenge - those expressions are priceless, and the camera control and quick reactions needed to get a composition with technicals as good as this with such a fast moving subject shouldn''t be under-estimated.', '2008-08-08 08:50:00.000000', NULL, 1),
(4874795, 706453, 67258, '<td valign="top">The haloing around the cyclists detracts a little, but nonethe less an impressive photo thta nails the challenge, and easily up there in my top 5.  Hope he didn''t do a face-plant!</td>', 'The haloing around the cyclists detracts a little, but nonethe less an impressive photo thta nails the challenge, and easily up there in my top 5.  Hope he didn''t do a face-plant!', '2008-08-08 08:51:11.000000', NULL, 1),
(4874797, 705734, 67258, '<td valign="top">I really like this - sad and poignant, and ambiguous in its intent.  Forces the viewer into really looking.  Good work.</td>', 'I really like this - sad and poignant, and ambiguous in its intent.  Forces the viewer into really looking.  Good work.', '2008-08-08 08:52:15.000000', NULL, 1),
(4874798, 705691, 67258, '<td valign="top">I couldn''t decide from viewing this whether it is a real child in silhouette, or a photograph of a peice of existing artwork.  I am going to assume the former, and am thoroughly impressed by it.</td>', 'I couldn''t decide from viewing this whether it is a real child in silhouette, or a photograph of a peice of existing artwork.  I am going to assume the former, and am thoroughly impressed by it.', '2008-08-08 08:53:35.000000', NULL, 1),
(4874805, 706434, 67258, '<td valign="top">The names on the gravestones interest me - I assume the widows of the soldiers are  buried alongside their husbands?  Are the names of the soldiers to whom the graves belong on the other side of the stones?  Good  monotone conversion.  I am unsure about the prominence given to the central stone in the foreground - a little too ''in your face'' for me, but apart from that a strong composition.</td>', 'The names on the gravestones interest me - I assume the widows of the soldiers are  buried alongside their husbands?  Are the names of the soldiers to whom the graves belong on the other side of the stones?  Good  monotone conversion.  I am unsure about the prominence given to the central stone in the foreground - a little too ''in your face'' for me, but apart from that a strong composition.', '2008-08-08 08:57:23.000000', NULL, 1),
(4874808, 706334, 67258, '<td valign="top">An unusual perspective that works well.  Detail is good and style of post-processing suits the image.</td>', 'An unusual perspective that works well.  Detail is good and style of post-processing suits the image.', '2008-08-08 08:58:10.000000', NULL, 1),
(4874809, 706178, 67258, '<td valign="top">Serendipity or posed?  Either way an excellent idea for the challenge, and well photographed.</td>', 'Serendipity or posed?  Either way an excellent idea for the challenge, and well photographed.', '2008-08-08 08:58:53.000000', NULL, 1),
(4874811, 706043, 67258, '<td valign="top">Wenders?  A creative take, very well presented.</td>', 'Wenders?  A creative take, very well presented.', '2008-08-08 08:59:24.000000', NULL, 1),
(4874821, 705605, 70265, '<td valign="top">Her hair is great! Oh, and a great shot ...</td>', 'Her hair is great! Oh, and a great shot ...', '2008-08-08 09:03:58.000000', NULL, 1),
(4874822, 705725, 70265, '<td valign="top">Your style is so interesting ... and unique. I''m sure you''ll do well with this.</td>', 'Your style is so interesting ... and unique. I''m sure you''ll do well with this.', '2008-08-08 09:04:34.000000', NULL, 1),
(4874825, 706308, 70265, '<td valign="top">I like the PP a lot here.</td>', 'I like the PP a lot here.', '2008-08-08 09:05:02.000000', NULL, 1),
(4874827, 705987, 70265, '<td valign="top">What a catch!!</td>', 'What a catch!!', '2008-08-08 09:05:09.000000', NULL, 1),
(4874829, 706180, 70265, '<td valign="top">Beautiful clarity.</td>', 'Beautiful clarity.', '2008-08-08 09:05:27.000000', NULL, 1),
(4874830, 705737, 70265, '<td valign="top">He looks like a character ...</td>', 'He looks like a character ...', '2008-08-08 09:05:46.000000', NULL, 1),
