(4876948, 706276, 63269, '<td valign="top">I like the colors and the concept.</td>', 'I like the colors and the concept.', '2008-08-09 11:01:21.000000', NULL, 1),
(4876949, 706355, 63269, '<td valign="top">The lighting is a little harsh - it might be a good idea to wait until a different time of day, such as evening or morning. ideally a cloudy, over cast day would be best for a nice soft light, but perhaps you want that lovely blue sky.</td>', 'The lighting is a little harsh - it might be a good idea to wait until a different time of day, such as evening or morning. ideally a cloudy, over cast day would be best for a nice soft light, but perhaps you want that lovely blue sky.', '2008-08-09 11:04:24.000000', NULL, 1),
